//! Файл: settings/catalog/cpu.rs
//! Что делает: настройки задачи t157 (решения 336–338) — счёт процессора: параллельные точки подбора объёма, ранний
//! выход подбора, потоки котировки и графа DEX, общий предел потоков счёта с приоритетом. Все необязательные: не
//! заданы — бот считает как до t157, кроме повторного использования того, что не зависит от объёма (в логике, решение
//! 363 — настройки dex.quote_reuse нет). Значений нет.
//! Отдельный файл: base.rs и dex.rs — общие части каталога (не раздуваем).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, разделы «Подбор объёма», «Счёт процессора», «DEX»).

use super::{G, V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 336–338. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static CPU: &[SettingDef] = &[
    d("Подбор объёма", "size.parallel_points", K::Integer, L::Positive, "точек", G, "Решение 336 (задача t157): сколько независимых точек подбора объёма одного кандидата считать одновременно — сетка и изломы стакана пачками, уточнение всех пиков в ногу (по две точки на пик за шаг). Каждая точка — своя котировка DEX в своём потоке счёта, поэтому время одного кандидата по часам падает почти во столько раз, сколько свободных ядер; работы процессора столько же. Набор посчитанных точек и итог — те же, что по одной, пока не исчерпан size.max_evals. Сочетается с profit.calc_concurrency (кандидатов одновременно) и cpu.threads_max (потоков всего). Без cpu.threads_max не включается (иначе одновременных котировок до profit.calc_concurrency × точек без предела): точки по одной, в пояснении выбора объёма — «size.parallel_points не действует: не задана настройка cpu.threads_max». Не задана или 1 — по одной, как раньше. Необязательна").optional(),
    d("Подбор объёма", "size.bisect_probes", K::Integer, L::Positive, "проб", G, "Решение 336 (задача t157): сколько проб за шаг поиска границ объёма (наибольший — по бюджету и глубине, наименьший — по минимумам) считать одной пачкой: отрезок за шаг сужается в (пробы + 1) раз вместо 2 — шагов меньше, расчётов больше. Граница та же. Имеет смысл только вместе с size.parallel_points > 1. Не задана или 1 — двоичный поиск, как раньше. Необязательна").optional(),
    d("Подбор объёма", "size.early_exit_margin_usd", K::Decimal, L::NonNegative, "USDT", G, "Решение 337 (задача t157): ранний выход подбора объёма. После границ и сетки (и ещё раз после изломов стакана) лучшая посчитанная прибыль ниже «порог прибыли направления (money.min_profit_usd; у цикла DEX ↔ DEX — dex_dex.min_profit_usd) минус этот запас» — уточнение и финальная котировка не считаются, кандидат отклоняется с причиной «ранний выход подбора». Сделка может потеряться, только если уточнение или финальная котировка нашли бы прибыль выше лучшей по сетке больше чем на запас (у неровной кривой прибыли — умный маршрут, тики пулов). Больше запас — меньше риск и меньше экономии. Не задана — подбор до конца, как раньше. Необязательна").optional(),
    d("Счёт процессора", "cpu.threads_max", K::Integer, L::NonNegative, "потоков", G, "Решение 338 (задача t157): общий предел потоков тяжёлого счёта процесса — потоки котировки DEX (вне рабочих потоков tokio) и их помощники (dex.quote_threads, dex.graph_threads). Сверх предела котировка ждёт места (внутри срока profit.calc_timeout_ms), помощник не берётся (счёт идёт меньшим числом потоков). При заданной — dex.quote_cpu_max не действует (иначе кандидаты, ждущие общего места, держали бы места dex.quote_cpu_max перед котировкой сделки). Задача сделки целиком (предпроверка, пересчёт) — ярус «сделка», план цикла DEX ↔ DEX — «кандидат». Места делятся по приоритету: путь сделки (финальная котировка, котировки исполнения) > расчёт кандидатов > фон (экран, проверки, «без потолка», теневые, циклы, граф). Приём WebSocket, таймеры и узел в предел не входят. 0 или не задана — общего предела нет, как раньше. Необязательна").optional(),
    d("Счёт процессора", "cpu.reserve_deal", K::Integer, L::NonNegative, "потоков", G, "Решение 338: сколько мест cpu.threads_max берёт только путь сделки (кандидаты и фон их не занимают). Не задана — 0. Действует только при заданной cpu.threads_max. Необязательна").optional(),
    d("Счёт процессора", "cpu.reserve_calc", K::Integer, L::NonNegative, "потоков", G, "Решение 338: сколько мест cpu.threads_max сверх cpu.reserve_deal берут только путь сделки и кандидаты (фон их не занимает). Не задана — 0. Действует только при заданной cpu.threads_max. Необязательна").optional(),
    d("Счёт процессора", "cpu.helper_threads", K::Integer, L::NonNegative, "потоков", G, "Решение 336 (ревью t157 Н2): размер постоянного набора потоков-помощников (dex.quote_threads, dex.graph_threads): потоки создаются один раз, а не на каждый вызов и шаг сплита; меньше — лишние выходят, когда освободятся; больше — дорастают. Помощник берёт место cpu.threads_max без ожидания. Не задана — набор дорастает до наибольшего числа помощников, которое просили (только растёт). Необязательна").optional(),
    d("DEX", "dex.quote_threads", K::Integer, L::NonNegative, "потоков", V, "Решение 336 (задача t157): сколько потоков считает одну котировку графа — отбор лучших путей и каждый шаг сплита (пути считаются независимо, выбор — по порядку путей, итог тот же). Помощники берут места cpu.threads_max без ожидания (нет мест — меньше помощников). Имеет смысл при многих путях (dex.route_search_max_paths); на каждый шаг сплита помощники создаются заново (накладные — десятки микросекунд). 0, 1 или не задана — один поток, как раньше. Необязательна").dex_venue().optional(),
    d("DEX", "dex.graph_threads", K::Integer, L::NonNegative, "потоков", V, "Решение 336 (задача t157): сколько потоков считает фоновый граф и поиск циклов DEX ↔ DEX — полная сборка карты графа и оценка изменённых пулов (каждый пул независимо, карта та же), расчёт найденных циклов (итоги по порядку путей). Места — cpu.threads_max ярусом «фон». 0, 1 или не задана — один поток, как раньше. Необязательна").dex_venue().optional(),
];
